// Dev tool: regenerates src/drivers/mssql/connectionOptions.generated.ts from
// docs/reference/mssql-capabilities.json (captured by tools/sts-probe.js).
// Usage: node tools/gen-mssql-connection-options.js
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const provider = require(path.join(root, "docs/reference/mssql-capabilities.json")).capabilities
    .connectionProvider;

const header = [
    "// Generated by tools/gen-mssql-connection-options.js from docs/reference/mssql-capabilities.json",
    "// (the connectionProvider section returned by Microsoft's sqltoolsservice).",
    "// Names, groups, order and display names are kept exactly as Microsoft returns them.",
    "",
    'import type { ConnectionProviderOptions } from "vscode-mssql";',
    "",
    "export const sqlToolsConnectionProvider: ConnectionProviderOptions = ",
].join("\n");

fs.writeFileSync(
    path.join(root, "src/drivers/mssql/connectionOptions.generated.ts"),
    header + JSON.stringify(provider, null, 4) + ";\n",
);
